module beautiful_rectangle #(\n    parameter MAX_DISTINCT = 8,\n    parameter MAX_P = 4,\n    parameter MAX_Q = 4\n) (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] number_values [0:MAX_DISTINCT-1],\n    input wire [4:0] count_values [0:MAX_DISTINCT-1],\n    input wire [3:0] valid_distinct,\n    output reg [15:0] area,\n    output reg [3:0] p,\n    output reg [3:0] q,\n    output reg [31:0] matrix [0:MAX_P-1][0:MAX_Q-1],\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] GENERATE_SEQ = 2'd2;\n    localparam [1:0] FILL = 2'd3;\n    localparam [1:0] DONE = 2'd4;\n\n    reg [1:0] state;\n    reg [3:0] p_iter;\n    reg [15:0] total_usable;\n    reg [15:0] best_area;\n    reg [3:0] best_p;\n    reg [3:0] best_q;\n    reg [3:0] dist_index;\n    reg [15:0] q_temp;\n    reg [7:0] cells_filled;\n    reg [3:0] seq_len;\n    reg [3:0] seq_idx;\n    reg [31:0] seq [0:15];\n    reg [3:0] row_reg;\n    reg [3:0] col_reg;\n    reg [3:0] current_dist_idx;\n    reg [4:0] copies_left;\n    reg [31:0] num_reg [0:MAX_DISTINCT-1];\n    reg [4:0] cnt_reg [0:MAX_DISTINCT-1];\n    reg [3:0] valid_distinct_reg;\n\n    function [4:0] min5(input [4:0] a, input [4:0] b);\n        min5 = (a < b) ? a : b;\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            area <= 16'd0;\n            p <= 4'd0;\n            q <= 4'd0;\n            best_area <= 16'd0;\n            best_p <= 4'd0;\n            best_q <= 4'd0;\n            p_iter <= 4'd4;\n            total_usable <= 16'd0;\n            dist_index <= 4'd0;\n            q_temp <= 16'd0;\n            cells_filled <= 8'd0;\n            seq_len <= 4'd0;\n            seq_idx <= 4'd0;\n            row_reg <= 4'd0;\n            col_reg <= 4'd0;\n            current_dist_idx <= 4'd0;\n            copies_left <= 5'd0;\n            valid_distinct_reg <= 4'd0;\n            // Initialize matrix\n            integer i, j;\n            for (i = 0; i < MAX_P; i = i + 1) begin\n                for (j = 0; j < MAX_Q; j = j + 1) begin\n                    matrix[i][j] <= 32'd0;\n                end\n            end\n            // Initialize arrays\n            for (i = 0; i < MAX_DISTINCT; i = i + 1) begin\n                num_reg[i] <= 32'd0;\n                cnt_reg[i] <= 5'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        valid_distinct_reg <= valid_distinct;\n                        for (integer i = 0; i < MAX_DISTINCT; i = i + 1) begin\n                            num_reg[i] <= number_values[i];\n                            cnt_reg[i] <= count_values[i];\n                        end\n                        p_iter <= 4'd4;\n                        best_area <= 16'd0;\n                        best_p <= 4'd0;\n                        best_q <= 4'd0;\n                        state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (p_iter >= 1) begin\n                        // Compute total usable for this p_iter\n                        if (dist_index < valid_distinct_reg) begin\n                            if (cnt_reg[dist_index] > p_iter)\n                                total_usable <= total_usable + p_iter;\n                            else\n                                total_usable <= total_usable + cnt_reg[dist_index];\n                            dist_index <= dist_index + 1;\n                        end else begin\n                            // After processing all numbers, compute q\n                            q_temp <= total_usable / p_iter;\n                            if (q_temp >= p_iter && p_iter * q_temp > best_area) begin\n                                best_area <= p_iter * q_temp;\n                                best_p <= p_iter;\n                                best_q <= q_temp;\n                            end\n                            p_iter <= p_iter - 1;\n                            dist_index <= 4'd0;\n                            total_usable <= 16'd0;\n                        end\n                    end else begin\n                        // Finished all heights\n                        if (best_area > 0) begin\n                            p <= best_p;\n                            q <= best_q;\n                            area <= best_area;\n                            state <= GENERATE_SEQ;\n                            seq_len <= 4'd0;\n                            current_dist_idx <= 4'd0;\n                            copies_left <= 5'd0;\n                        end else begin\n                            // No rectangle possible (should not happen with valid input)\n                            area <= 16'd0;\n                            p <= 4'd0;\n                            q <= 4'd0;\n                            state <= DONE;\n                            done <= 1'b1;\n                        end\n                    end\n                end\n\n                GENERATE_SEQ: begin\n                    if (seq_len < best_area) begin\n                        // If current number has no copies left, move to next\n                        if (copies_left == 0) begin\n                            // Find next number with remaining count\n                            if (current_dist_idx < valid_distinct_reg) begin\n                                // Skip zeros (should not happen if counts are positive)\n                                if (cnt_reg[current_dist_idx] == 0) begin\n                                    current_dist_idx <= current_dist_idx + 1;\n                                end\n                                // Set copies_left to min(count, best_p)\n                                copies_left <= min5(cnt_reg[current_dist_idx], best_p);\n                            end\n                        end\n                        // Assign number to sequence\n                        seq[seq_len] <= num_reg[current_dist_idx];\n                        seq_len <= seq_len + 1;\n                        // Decrement counters\n                        cnt_reg[current_dist_idx] <= cnt_reg[current_dist_idx] - 1;\n                        copies_left <= copies_left - 1;\n                    end else begin\n                        // Sequence generation complete\n                        seq_idx <= 4'd0;\n                        row_reg <= 4'd0;\n                        col_reg <= 4'd0;\n                        state <= FILL;\n                    end\n                end\n\n                FILL: begin\n                    if (seq_idx < best_area) begin\n                        // Assign to matrix at diagonal position\n                        matrix[row_reg][(col_reg + row_reg) % best_q] <= seq[seq_idx];\n                        seq_idx <= seq_idx + 1;\n                        // Move to next cell\n                        if (row_reg == best_p - 1) begin\n                            row_reg <= 4'd0;\n                            if (col_reg == best_q - 1) begin\n                                col_reg <= 4'd0;\n                            end else begin\n                                col_reg <= col_reg + 1;\n                            end\n                        end else begin\n                            row_reg <= row_reg + 1;\n                        end\n                    end else begin\n                        state <= DONE;\n                        done <= 1'b1;\n                    end\n                end\n\n                DONE: begin\n                    // Hold done\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule